function validateContract(payload, name) {
  if (payload?.schema_version !== DATA_SCHEMA) throw new Error(`${name}: versiune contract ${payload?.schema_version || 'lipsa'}; asteptat ${DATA_SCHEMA}`);
}
async function fetchJson(path, token) {
  const response = await fetch(path, { headers:token ? { Authorization:`Bearer ${token}` } : {}, cache:'no-store' });
  let payload=null; try { payload=await response.json(); } catch { payload=null; }
  if (!response.ok) { const error=new Error(payload?.error || `${path}: HTTP ${response.status}`); error.status=response.status; error.path=path; throw error; }
  return payload;
}
async function commandApi(path, token, options={}) {
  const headers={...(options.headers||{})}; if(token)headers.Authorization=`Bearer ${token}`; if(options.body&&!headers['Content-Type'])headers['Content-Type']='application/json';
  const response=await fetch(path,{...options,headers,cache:'no-store'}); let payload=null; try{payload=await response.json();}catch{payload=null;}
  if(!response.ok){const error=new Error(payload?.error||`HTTP ${response.status}`);error.status=response.status;throw error;} return payload;
}
function ageHours(value,fallback=0){if(!value)return Number.isFinite(Number(fallback))?Number(fallback):0;const ms=Date.now()-new Date(value).getTime();return Number.isFinite(ms)?Math.max(0,Math.floor(ms/3600000)):Number(fallback)||0;}
function normalizeMode(value){const raw=String(value||'').trim().toLowerCase();if(raw==='remote')return'Remote';if(raw==='hybrid')return'Hybrid';if(['onsite','on-site','office','in-office'].includes(raw))return'Onsite';return'N/A';}
function stableSourceId(url){let hash=2166136261;for(const char of String(url||'').toLowerCase()){hash^=char.charCodeAt(0);hash=Math.imul(hash,16777619);}return`src-${(hash>>>0).toString(16).padStart(8,'0')}`;}
function countryName(code){return COUNTRY_NAMES[String(code||'').toUpperCase()]||String(code||'').toUpperCase();}
function normalizedCountries(job){
  const names=Array.isArray(job.countries)?job.countries.map(x=>typeof x==='string'?x:x?.name).filter(Boolean):[];
  const codes=Array.isArray(job.country_codes)?job.country_codes.filter(Boolean):job.country_code?[job.country_code]:[];
  for(const code of codes){const name=countryName(code);if(name&&!names.includes(name))names.push(name);}
  if(!names.length&&job.remote_scope&&job.remote_scope!=='Unknown'&&job.remote_scope!=='Country')names.push(job.remote_scope);
  return names;
}
function countryCompact(job){const list=job.countries||[];if(!list.length)return'Nespecificat';return list.length===1?list[0]:`${list[0]} +${list.length-1}`;}
function normalizeJob(job){const countries=normalizedCountries(job);return{
  id:job.id||null,title:job.title||'Titlu indisponibil',company:job.company||'Companie nespecificata',initial:job.initial||((job.company||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'?'),
  fit:Number.isFinite(Number(job.fit))?Number(job.fit):0,location:job.location||'Nespecificat',countries,countryCodes:Array.isArray(job.country_codes)?job.country_codes:[],remoteScope:job.remote_scope||'Unknown',mode:normalizeMode(job.mode),type:job.type||'Nespecificat',age:ageHours(job.date_posted,job.age),
  remote:Boolean(job.remote),b2b:Boolean(job.b2b),repost:Boolean(job.repost),status:job.status||'review',pros:Array.isArray(job.pros)?job.pros:[],risks:Array.isArray(job.risks)?job.risks:[],url:job.url||null,
  description:String(job.description||'').trim(),date_posted:job.date_posted||null,source:job.source||'Nespecificata',verified_at:job.verified_at||null,isApplication:false,
};}
function inferApplicationCountry(location){return /\b(Timisoara|Bucuresti|Bucharest|Cluj|Iasi|Brasov|Romania)\b/i.test(String(location||''))?['Romania']:[];}
function normalizeApplication(application){const ref=application.reference?`Referinta: ${application.reference}`:'Referinta nespecificata';const next=application.next_status_check?`Urmatorul status check: ${application.next_status_check}`:'Status check nespecificat';const countries=Array.isArray(application.countries)?application.countries:inferApplicationCountry(application.location);return{
  id:application.id||`application-${application.company||''}-${application.title||''}-${application.applied_at||''}`,title:application.title||'Rol nespecificat',company:application.company||'Companie nespecificata',initial:(application.company||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'?',fit:null,
  location:application.location||'Nespecificat',countries,countryCodes:[],remoteScope:'Unknown',mode:'N/A',type:'Aplicat',age:0,remote:false,b2b:false,repost:false,status:application.status||'applied',pros:[`Aplicat: ${application.applied_at||'data nespecificata'}`,ref],risks:[next],url:application.url||null,
  description:`Status: ${application.status||'applied'}. ${ref}. ${next}.`,source:'Istoric aplicari',date_posted:application.applied_at||null,isApplication:true,
};}
function criteriaFromConfig(config){const groups=config?.role_groups||{},modes=config?.work_modes||{};const legacyMode=config?.jobspipe_enabled===true?'direct':'disabled';return{
  rolePm:groups.pm?.enabled!==false,roleDelivery:groups.delivery?.enabled!==false,roleService:groups.service?.enabled!==false,roleScrum:groups.scrum?.enabled!==false,roleProgram:groups.program?.enabled!==false,workRemote:modes.remote!==false,workHybrid:modes.hybrid!==false,
  freshness:Number(config?.freshness_hours??24),fitThreshold:Number(config?.fit_threshold??80),keepReposts:config?.keep_reposts!==false,rateMin:Number(config?.rate_min_eur_day??250),rateMax:Number(config?.rate_max_eur_day??650),immediateStart:config?.immediate_start!==false,
  jobspipeMode:config?.jobspipe_mode||legacyMode,jobspipeApifyMaxItems:Number(config?.jobspipe_apify_max_items_per_run??5000),jobspipeDirectRunBudget:Number(config?.jobspipe_credit_budget_per_run??14),jobspipeDirectMonthlyGuard:Number(config?.jobspipe_monthly_credit_guard??950),
  exclusions:Array.isArray(config?.exclusions)?[...config.exclusions]:[],targetRegions:Array.isArray(config?.target_regions)?[...config.target_regions]:[],targetCountries:Array.isArray(config?.target_country_codes)?[...config.target_country_codes]:Array.isArray(config?.search_country_codes)?[...config.search_country_codes]:[],excludedRegions:Array.isArray(config?.excluded_regions)?[...config.excluded_regions]:[],excludedCountries:Array.isArray(config?.excluded_country_codes)?[...config.excluded_country_codes]:[],
};}
function normalizeSource(source){return{id:source.id||stableSourceId(source.url),category:source.category||'Altele',name:source.name||'Sursa',url:source.url||'#',active:source.active!==false,connectorAvailable:Boolean(source.connector_available)};}
const jobKey=job=>String(job.id||`${job.title}|${job.company}|${job.date_posted||''}`);
function publishedLabel(job){if(job.isApplication)return job.date_posted?`aplicat ${job.date_posted}`:'aplicat';const age=ageHours(job.date_posted,job.age);if(age<1)return'sub 1h';if(age<24)return`${age}h`;const days=Math.floor(age/24),hours=age%24;return hours?`${days}z ${hours}h`:`${days}z`;}
function formatRunTime(value){if(!value)return'—';try{return new Intl.DateTimeFormat('ro-RO',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Bucharest'}).format(new Date(value));}catch{return value;}}
function geographyConflicts(criteria){
  const targetR=new Set(criteria.targetRegions||[]),excludedR=new Set(criteria.excludedRegions||[]),targetC=new Set(criteria.targetCountries||[]),excludedC=new Set(criteria.excludedCountries||[]);
  for(const x of targetR)if(excludedR.has(x))return true;for(const x of targetC)if(excludedC.has(x))return true;
  for(const r of targetR)for(const c of excludedC)if(REGION_COUNTRIES[r]?.has(c))return true;for(const r of excludedR)for(const c of targetC)if(REGION_COUNTRIES[r]?.has(c))return true;return false;
}

function loadGoogleIdentityScript(){if(window.google?.accounts?.id)return Promise.resolve();return new Promise((resolve,reject)=>{const existing=document.querySelector('script[data-google-identity]');if(existing){existing.addEventListener('load',resolve,{once:true});existing.addEventListener('error',reject,{once:true});return;}const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.defer=true;script.dataset.googleIdentity='true';script.onload=resolve;script.onerror=()=>reject(new Error('Google Identity Services nu a putut fi incarcat.'));document.head.appendChild(script);});}
function GoogleSignIn({clientId,onCredential,disabled}){const ref=useRef(null);useEffect(()=>{let active=true;if(!clientId||disabled)return undefined;loadGoogleIdentityScript().then(()=>{if(!active||!ref.current)return;window.google.accounts.id.initialize({client_id:clientId,callback:({credential})=>onCredential(credential),auto_select:false,cancel_on_tap_outside:true});ref.current.innerHTML='';window.google.accounts.id.renderButton(ref.current,{theme:'outline',size:'large',shape:'rectangular',text:'signin_with'});}).catch(()=>{});return()=>{active=false;};},[clientId,disabled,onCredential]);return<div ref={ref} className={disabled?'pointer-events-none opacity-60':''}/>;}
function Toast({toast}){if(!toast)return null;return<div className={cx('fixed bottom-5 right-5 z-[90] max-w-sm rounded-xl border bg-white px-4 py-3 text-sm text-slate-800 shadow-lg',toast.type==='success'?'border-emerald-200':toast.type==='error'?'border-red-200':'border-slate-200')} role="status"><div className="flex items-start gap-3"><span className={cx('mt-0.5 h-2.5 w-2.5 shrink-0 rounded-full',toast.type==='success'?'bg-emerald-500':toast.type==='error'?'bg-red-500':'bg-slate-400')}/><span>{toast.message}</span></div></div>;}
function Brand(){return<div className="flex items-center gap-3 px-5 py-5"><div className="grid h-10 w-10 place-items-center rounded-xl bg-blue-600 text-lg font-bold text-white shadow-sm">S</div><span className="font-display text-lg font-bold tracking-tight text-white">Job Search</span></div>;}
function SignedOutScreen({clientId,authError,authStatus,onCredential}){return<div className="min-h-screen bg-slate-50 md:flex"><aside className="bg-slate-950 md:min-h-screen md:w-64 md:shrink-0"><Brand/></aside><main className="flex min-h-[calc(100vh-80px)] flex-1 items-start justify-center p-6 pt-10 md:min-h-screen md:justify-start md:p-12"><div className="w-full max-w-sm rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><h1 className="font-display text-xl font-bold text-slate-900">Acces securizat</h1><p className="mt-1 text-sm text-slate-500">Autentifica-te cu contul Google autorizat.</p><div className="mt-5 min-h-11">{clientId?<GoogleSignIn clientId={clientId} onCredential={onCredential} disabled={authStatus==='authenticating'}/>:<div className="h-11 animate-pulse rounded-lg bg-slate-100"/>}</div>{authStatus==='authenticating'&&<p className="mt-3 text-sm text-slate-500">Se verifica sesiunea...</p>}{authError&&<div className="mt-4 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">{authError}</div>}</div></main></div>;}

function SidebarBadge({value,active}){return<span className={cx('ml-auto min-w-6 rounded-full px-2 py-0.5 text-center text-xs font-semibold text-white',active?'bg-blue-500':'bg-slate-700')}>{value}</span>;}
function Sidebar({view,onView,counts,runStatus}){
  const items=[['jobs','Joburi noi','jobs',counts.jobs],['review','De evaluat','review',counts.review],['applications','Aplicari','applications',counts.applications],['criteria','Criterii de selectie','criteria',null],['sources','Surse','sources',null],['logs','Loguri','logs',null]];
  const statusTone=runStatus?.status==='completed'?'bg-emerald-500':runStatus?.status==='running'?'bg-blue-500':runStatus?.status==='completed_with_errors'?'bg-amber-500':'bg-red-500';
  return<aside className="bg-slate-950 text-slate-300 md:sticky md:top-0 md:flex md:h-screen md:w-64 md:shrink-0 md:flex-col"><Brand/><nav className="space-y-1 px-3">{items.map(([key,label,icon,count])=><button key={key} onClick={()=>onView(key)} className={cx('flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm font-medium transition',view===key?'bg-slate-800 text-white':'hover:bg-slate-900 hover:text-white')}><Icon name={icon}/><span>{label}</span>{count!==null&&<SidebarBadge value={count} active={view===key}/>}</button>)}</nav><div className="mt-auto border-t border-slate-800 p-4"><div className="flex items-center gap-2 text-xs text-slate-400"><span className={cx('h-2 w-2 rounded-full',statusTone)}/><span>Ultima rulare</span></div><div className="mt-1 text-xs text-slate-500">{formatRunTime(runStatus?.completed_at||runStatus?.started_at)} · {runStatus?.sources_processed??runStatus?.sources?.length??0} surse</div><div className="mt-3 text-[11px] text-slate-600">v0.05</div></div></aside>;
}
function ProfileMenu({email,onLogout}){const[open,setOpen]=useState(false),ref=useRef(null);const initial=(email||'G').slice(0,1).toUpperCase();useEffect(()=>{const handler=e=>{if(ref.current&&!ref.current.contains(e.target))setOpen(false)};document.addEventListener('mousedown',handler);return()=>document.removeEventListener('mousedown',handler);},[]);return<div className="relative" ref={ref}><button onClick={()=>setOpen(v=>!v)} className="flex h-10 items-center gap-2 rounded-xl border border-slate-200 bg-white px-2.5 text-sm text-slate-700 shadow-sm transition hover:bg-slate-50"><span className="grid h-7 w-7 place-items-center rounded-full bg-slate-100 text-xs font-bold text-slate-700">{initial}</span><span className="hidden max-w-40 truncate lg:block">{email||'Google conectat'}</span><Icon name="chevronDown" className="h-4 w-4 text-slate-400"/></button>{open&&<div className="absolute right-0 z-50 mt-2 w-64 rounded-xl border border-slate-200 bg-white p-2 shadow-lg"><div className="px-3 py-2"><div className="text-xs font-medium uppercase tracking-wide text-slate-400">Cont conectat</div><div className="mt-1 truncate text-sm font-medium text-slate-800">{email||'Google'}</div></div><div className="my-1 border-t border-slate-100"/><button onClick={onLogout} className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-sm text-slate-600 hover:bg-slate-50 hover:text-slate-900"><Icon name="logout"/> Deconecteaza</button></div>}</div>;}
function Header({view,email,running,onRun,onLogout}){const titles={jobs:'Joburi noi',review:'De evaluat',applications:'Aplicari',criteria:'Criterii de selectie',sources:'Surse',logs:'Loguri'};const date=new Intl.DateTimeFormat('ro-RO',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Bucharest'}).format(new Date()).toUpperCase();return<header className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><div className="text-xs font-semibold tracking-[0.16em] text-slate-400">{date}</div><h1 className="mt-1 font-display text-2xl font-bold tracking-tight text-slate-950">{titles[view]}</h1></div><div className="flex items-center gap-2">{view!=='criteria'&&<button onClick={onRun} disabled={running} className="inline-flex h-10 items-center gap-2 rounded-xl bg-blue-600 px-4 text-sm font-semibold text-white shadow-sm transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-60"><Icon name="refresh" className={cx('h-4 w-4',running&&'animate-spin')}/>{running?'Verificare in curs...':'Ruleaza verificarea'}</button>}<ProfileMenu email={email} onLogout={onLogout}/></div></header>;}

function MetricCard({value,label,note,icon,tone='blue',active,onClick}){const tones={blue:'bg-blue-50 text-blue-600',amber:'bg-amber-50 text-amber-600',violet:'bg-violet-50 text-violet-600',slate:'bg-slate-100 text-slate-600'};return<button onClick={onClick} className={cx('w-full rounded-2xl border bg-white p-4 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-md',active?'border-blue-400 ring-4 ring-blue-50':'border-slate-200')}><div className="flex items-start gap-3"><span className={cx('grid h-9 w-9 place-items-center rounded-xl',tones[tone])}><Icon name={icon}/></span><div><div className="text-2xl font-bold leading-none text-slate-950">{value}</div><div className="mt-1 text-sm text-slate-600">{label}</div><div className="mt-1 text-xs text-slate-400">{note}</div></div></div></button>;}
function KPIGrid({metrics,freshness,selected,onSelect}){const toggle=key=>onSelect(selected===key?'all':key);return<section className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4" aria-label="Rezumat"><MetricCard value={metrics.jobs} label="roluri noi" note="ultimele 24h" icon="jobs" tone="blue" active={selected==='new'} onClick={()=>toggle('new')}/><MetricCard value={metrics.high} label="fit ridicat" note={`>= ${metrics.threshold}%`} icon="review" tone="slate" active={selected==='high'} onClick={()=>toggle('high')}/><MetricCard value={metrics.reposts} label="repostari" note="marcate, nu ascunse" icon="refresh" tone="amber" active={selected==='repost'} onClick={()=>toggle('repost')}/><MetricCard value={metrics.remote} label="remote" note="eligibile din Romania" icon="globe" tone="violet" active={selected==='remote'} onClick={()=>toggle('remote')}/></section>;}
function FilterButton({active,onClick,children,count}){return<button onClick={onClick} className={cx('inline-flex h-9 items-center gap-2 rounded-full border px-3 text-sm font-medium transition',active?'border-blue-200 bg-blue-50 text-blue-700':'border-slate-200 bg-white text-slate-600 hover:bg-slate-50')}>{children}{count!==undefined&&<span className={cx('rounded-full px-1.5 py-0.5 text-[11px] font-semibold',active?'bg-blue-100 text-blue-700':'bg-slate-100 text-slate-500')}>{count}</span>}</button>;}
function WorkModeDropdown({selected,onChange}){const[open,setOpen]=useState(false),ref=useRef(null);useEffect(()=>{const h=e=>{if(ref.current&&!ref.current.contains(e.target))setOpen(false)};document.addEventListener('mousedown',h);return()=>document.removeEventListener('mousedown',h)},[]);const label=selected.length===ALL_WORK_MODES.length?'Toate':selected.length===0?'Niciunul':selected.join(', ');const toggle=mode=>onChange(selected.includes(mode)?selected.filter(x=>x!==mode):[...selected,mode]);return<div className="relative" ref={ref}><button onClick={()=>setOpen(v=>!v)} className="inline-flex h-9 items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 text-sm font-medium text-slate-600 hover:bg-slate-50">Mod lucru: <span className="max-w-36 truncate text-slate-800">{label}</span><Icon name="chevronDown" className="h-4 w-4 text-slate-400"/></button>{open&&<div className="absolute left-0 z-40 mt-2 w-48 rounded-xl border border-slate-200 bg-white p-2 shadow-lg">{ALL_WORK_MODES.map(mode=><label key={mode} className="flex cursor-pointer items-center gap-2 rounded-lg px-2.5 py-2 text-sm text-slate-700 hover:bg-slate-50"><input type="checkbox" className="h-4 w-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500" checked={selected.includes(mode)} onChange={()=>toggle(mode)}/>{mode==='Hybrid'?'Hibrid':mode}</label>)}</div>}</div>;}
function Filters({filters,setFilters,counts,defaultFreshness,onResetKpi}){const reset=()=>{setFilters({search:'',quick:'all',freshness:defaultFreshness||24,workModes:[...ALL_WORK_MODES],sort:'fit-desc'});onResetKpi?.();};return<div className="rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="border-b border-slate-100 p-4"><label className="relative block"><Icon name="search" className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"/><input value={filters.search} onChange={e=>setFilters(v=>({...v,search:e.target.value}))} type="search" placeholder="Cauta rol, companie sau tehnologie" className="h-11 w-full rounded-xl border border-slate-200 bg-slate-50 pl-10 pr-4 text-sm text-slate-800 outline-none transition placeholder:text-slate-400 focus:border-blue-400 focus:bg-white focus:ring-4 focus:ring-blue-50"/></label></div><div className="flex flex-wrap items-center gap-2 p-4"><FilterButton active={filters.quick==='all'} onClick={()=>setFilters(v=>({...v,quick:'all'}))} count={counts.all}>Toate</FilterButton><FilterButton active={filters.quick==='high'} onClick={()=>setFilters(v=>({...v,quick:'high'}))} count={counts.high}>Fit ridicat</FilterButton><FilterButton active={filters.quick==='b2b'} onClick={()=>setFilters(v=>({...v,quick:'b2b'}))} count={counts.b2b}>B2B</FilterButton><select value={filters.freshness} onChange={e=>setFilters(v=>({...v,freshness:Number(e.target.value)}))} className="h-9 rounded-xl border border-slate-200 bg-white px-3 text-sm font-medium text-slate-600 outline-none"><option value={24}>24h</option><option value={36}>36h</option><option value={48}>48h</option><option value={120}>5 zile</option></select><WorkModeDropdown selected={filters.workModes} onChange={workModes=>setFilters(v=>({...v,workModes}))}/><select value={filters.sort} onChange={e=>setFilters(v=>({...v,sort:e.target.value}))} className="h-9 rounded-xl border border-slate-200 bg-white px-3 text-sm font-medium text-slate-600 outline-none"><option value="fit-desc">FIT descrescator</option><option value="fit-asc">FIT crescator</option></select><button onClick={reset} className="ml-auto inline-flex h-9 items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 text-sm font-medium text-slate-600 hover:bg-slate-50"><Icon name="reset"/> Reseteaza filtrele</button></div></div>;}
function FitBadge({fit,threshold}){if(fit===null||fit===undefined)return<span className="text-sm text-slate-400">—</span>;return<span className={cx('inline-flex min-w-12 justify-center rounded-full px-2 py-1 text-xs font-semibold',fit>=threshold?'bg-blue-50 text-blue-700':'bg-slate-100 text-slate-600')}>{fit}%</span>;}
function ModeBadge({mode}){const tone=mode==='Remote'?'bg-violet-50 text-violet-700':mode==='Hybrid'?'bg-amber-50 text-amber-700':'bg-slate-100 text-slate-600';return<span className={cx('inline-flex rounded-full px-2 py-1 text-xs font-medium',tone)}>{mode==='Hybrid'?'Hibrid':mode}</span>;}
function JobTable({rows,threshold,onDetails,onArchive}){if(!rows.length)return<div className="rounded-2xl border border-slate-200 bg-white px-6 py-14 text-center text-sm text-slate-500 shadow-sm">Niciun rol nu corespunde filtrelor.</div>;return<div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="hidden grid-cols-[minmax(0,1fr)_150px_80px_105px_95px_112px] gap-3 border-b border-slate-100 bg-slate-50/70 px-5 py-2 text-[11px] font-semibold uppercase tracking-wide text-slate-400 md:grid"><span>Rol</span><span>Tara</span><span>Fit</span><span>Mod lucru</span><span>Publicat</span><span className="text-right">Actiuni</span></div><div className="divide-y divide-slate-100">{rows.map(job=><div key={jobKey(job)} onClick={()=>onDetails(job)} className="group grid cursor-pointer gap-3 px-4 py-3 transition hover:bg-slate-50 md:grid-cols-[minmax(0,1fr)_150px_80px_105px_95px_112px] md:items-center md:px-5"><div className="flex min-w-0 items-start gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-slate-100 text-xs font-bold text-slate-600">{job.initial}</span><div className="min-w-0"><div className="truncate text-sm font-semibold text-slate-900">{job.title}</div><div className="mt-0.5 flex flex-wrap items-center gap-1.5 text-xs text-slate-500"><span className="truncate">{job.company} · {job.location}</span>{job.repost&&<span className="rounded-full bg-amber-50 px-1.5 py-0.5 text-amber-700">Repostare</span>}{job.type&&<span className="rounded-full bg-slate-100 px-1.5 py-0.5 text-slate-500">{job.type}</span>}</div></div></div><div className="text-xs font-medium text-slate-600">{countryCompact(job)}</div><div><FitBadge fit={job.fit} threshold={threshold}/></div><div><ModeBadge mode={job.mode}/></div><div className="text-xs font-medium text-slate-500">{publishedLabel(job)}</div><div className="flex items-center justify-end gap-1 opacity-100 transition md:opacity-0 md:group-hover:opacity-100" onClick={e=>e.stopPropagation()}>{!job.isApplication&&<button onClick={()=>onArchive(job)} title="Arhiveaza" className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700"><Icon name="archive"/></button>}{job.url&&<a href={job.url} target="_blank" rel="noopener noreferrer" title="Aplica" className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700"><Icon name="external"/></a>}<button onClick={()=>onDetails(job)} title="Vezi detalii" className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700"><Icon name="eye"/></button></div></div>)}</div></div>;}
function ErrorPanel({error,onRetry}){return<div className="rounded-2xl border border-red-200 bg-white p-6 shadow-sm"><div className="flex items-start gap-4"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-red-50 text-red-600"><Icon name="alert" className="h-5 w-5"/></span><div className="min-w-0 flex-1"><h2 className="font-display text-base font-bold text-slate-900">Datele nu au putut fi incarcate</h2><p className="mt-1 break-words text-sm text-slate-600">Autentificarea Google este valida, dar accesul la date a esuat: {error?.message||'eroare necunoscuta'}.</p><button onClick={onRetry} className="mt-4 inline-flex h-9 items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 text-sm font-semibold text-slate-700 hover:bg-slate-50"><Icon name="retry"/> Reincearca incarcarea</button></div></div></div>;}
function LoadingPanel(){return<div className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div className="flex items-center gap-3 text-sm text-slate-500"><span className="h-4 w-4 animate-spin rounded-full border-2 border-slate-200 border-t-blue-600"/> Se incarca datele protejate...</div></div>;}
function DetailDrawer({job,threshold,onClose}){if(!job)return null;return<><button className="fixed inset-0 z-50 bg-slate-950/25" onClick={onClose} aria-label="Inchide detaliile"/><aside className="fixed inset-y-0 right-0 z-[60] w-full max-w-xl overflow-y-auto border-l border-slate-200 bg-white shadow-2xl"><div className="sticky top-0 flex items-center justify-between border-b border-slate-100 bg-white/95 px-6 py-4 backdrop-blur"><div className="text-xs font-semibold uppercase tracking-[0.14em] text-slate-400">Detalii job</div><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-lg text-slate-500 hover:bg-slate-100"><Icon name="close" className="h-5 w-5"/></button></div><div className="space-y-6 p-6"><div><h2 className="font-display text-2xl font-bold text-slate-950">{job.title}</h2><p className="mt-1 text-sm text-slate-500">{job.company}</p></div><div className="grid grid-cols-2 gap-3"><div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">FIT</div><div className="mt-1"><FitBadge fit={job.fit} threshold={threshold}/></div></div><div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">Mod lucru</div><div className="mt-1"><ModeBadge mode={job.mode}/></div></div><div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">Locatie</div><div className="mt-1 text-sm font-medium text-slate-700">{job.location}</div></div><div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">Tara / tari</div><div className="mt-1 text-sm font-medium text-slate-700">{job.countries?.length?job.countries.join(', '):'Nespecificat'}</div></div>{job.remote&&<div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">Scope Remote</div><div className="mt-1 text-sm font-medium text-slate-700">{job.remoteScope}</div></div>}<div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">Sursa</div><div className="mt-1 text-sm font-medium text-slate-700">{job.source}</div></div></div>{job.pros?.length>0&&<div><h3 className="text-sm font-semibold text-slate-900">Puncte forte</h3><ul className="mt-2 space-y-2 text-sm text-slate-600">{job.pros.map((x,i)=><li key={i}>• {x}</li>)}</ul></div>}{job.risks?.length>0&&<div><h3 className="text-sm font-semibold text-slate-900">Riscuri</h3><ul className="mt-2 space-y-2 text-sm text-slate-600">{job.risks.map((x,i)=><li key={i}>• {x}</li>)}</ul></div>}<div><h3 className="text-sm font-semibold text-slate-900">Descriere</h3><div className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-600">{job.description||'Descriere indisponibila.'}</div></div>{job.url&&<a href={job.url} target="_blank" rel="noopener noreferrer" className="inline-flex h-10 items-center gap-2 rounded-xl bg-blue-600 px-4 text-sm font-semibold text-white hover:bg-blue-700">Deschide jobul <Icon name="external"/></a>}</div></aside></>;}

function CriteriaCard({title,note,children,className}){return<section className={cx('rounded-2xl border border-slate-200 bg-white p-4 shadow-sm',className)}><h2 className="font-display text-base font-bold text-slate-900">{title}</h2>{note&&<p className="mt-1 text-sm text-slate-500">{note}</p>}<div className="mt-3 space-y-3">{children}</div></section>;}
function CheckRow({checked,onChange,children,disabled=false}){return<label className={cx('flex items-start gap-3 text-sm text-slate-700',disabled?'cursor-not-allowed opacity-60':'cursor-pointer')}><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)} disabled={disabled} className="mt-0.5 h-4 w-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500"/><span>{children}</span></label>;}
function ChipsSelector({label,values,onChange,options,placeholder}){const available=options.filter(([value])=>!values.includes(value));return<div><div className="text-sm text-slate-700">{label}</div><select defaultValue="" onChange={e=>{if(e.target.value)onChange([...values,e.target.value]);e.target.value='';}} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-700 outline-none"><option value="">{placeholder}</option>{available.map(([value,text])=><option key={value} value={value}>{text}</option>)}</select><div className="mt-2 flex flex-wrap gap-2">{values.map(value=><button type="button" key={value} onClick={()=>onChange(values.filter(x=>x!==value))} className="inline-flex items-center gap-1 rounded-full bg-slate-100 px-2.5 py-1 text-xs font-medium text-slate-600 hover:bg-slate-200">{COUNTRY_NAMES[value]||value}<Icon name="close" className="h-3 w-3"/></button>)}</div></div>;}
function RegionSelector({label,values,onChange}){return<div><div className="text-sm text-slate-700">{label}</div><div className="mt-2 flex flex-wrap gap-2">{REGION_OPTIONS.map(region=><button type="button" key={region} onClick={()=>onChange(values.includes(region)?values.filter(x=>x!==region):[...values,region])} className={cx('rounded-full border px-3 py-1.5 text-xs font-semibold',values.includes(region)?'border-blue-200 bg-blue-50 text-blue-700':'border-slate-200 bg-white text-slate-600')}>{region==='ASIA'?'Asia':region}</button>)}</div></div>;}
function CriteriaPage({draft,setDraft,saved,onSave,saving}){const dirty=JSON.stringify(draft)!==JSON.stringify(saved),update=(key,value)=>setDraft(v=>({...v,[key]:value}));const addExclusion=value=>{if(value&&!draft.exclusions.includes(value))update('exclusions',[...draft.exclusions,value])},removeExclusion=value=>update('exclusions',draft.exclusions.filter(x=>x!==value));const conflict=geographyConflicts(draft);return<div className="space-y-5"><div className="grid grid-cols-1 gap-5 md:grid-cols-2"><CriteriaCard title="Roluri urmarite"><CheckRow checked={draft.rolePm} onChange={v=>update('rolePm',v)}>Project Manager / IT Project Manager</CheckRow><CheckRow checked={draft.roleDelivery} onChange={v=>update('roleDelivery',v)}>Delivery / Technical Project Manager</CheckRow><CheckRow checked={draft.roleService} onChange={v=>update('roleService',v)}>Service Manager</CheckRow><CheckRow checked={draft.roleScrum} onChange={v=>update('roleScrum',v)}>Scrum Master, fara nivel excesiv de senior</CheckRow><CheckRow checked={draft.roleProgram} onChange={v=>update('roleProgram',v)}>Program / PMO Manager</CheckRow></CriteriaCard><CriteriaCard title="Mod de lucru" note="Ordinea ramane Remote, Hibrid, apoi celelalte rezultate eligibile."><CheckRow checked={draft.workRemote} onChange={v=>update('workRemote',v)}>Remote</CheckRow><CheckRow checked={draft.workHybrid} onChange={v=>update('workHybrid',v)}>Hibrid</CheckRow></CriteriaCard><CriteriaCard title="Tara / regiune" note="Regiuni selectabile: EU, US, Asia. Tarile pot fi selectate individual."><RegionSelector label="Regiuni incluse" values={draft.targetRegions} onChange={v=>update('targetRegions',v)}/><ChipsSelector label="Tari incluse" values={draft.targetCountries} onChange={v=>update('targetCountries',v)} options={COUNTRY_OPTIONS} placeholder="Adauga o tara"/><div className="rounded-xl bg-slate-50 px-3 py-2 text-xs text-slate-500">Remote fara teritoriu explicit este Worldwide. Remote EU/EMEA este evaluat conform restrictiei, iar joburile cu tari explicite trebuie sa accepte Romania.</div></CriteriaCard><CriteriaCard title="Praguri de selectie"><label className="block text-sm text-slate-700">Vechimea implicita<select value={draft.freshness} onChange={e=>update('freshness',Number(e.target.value))} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value={24}>24 ore</option><option value={36}>36 ore</option><option value={48}>48 ore</option><option value={120}>5 zile</option></select></label><label className="block text-sm text-slate-700">Scor minim pentru fit ridicat<div className="mt-1.5 flex items-center gap-2"><input type="number" min="50" max="100" value={draft.fitThreshold} onChange={e=>update('fitThreshold',Number(e.target.value))} className="h-10 w-28 rounded-xl border border-slate-200 px-3 text-sm"/><span className="text-slate-400">%</span></div></label><CheckRow checked={draft.keepReposts} onChange={v=>update('keepReposts',v)}>Pastreaza si marcheaza repostarile</CheckRow></CriteriaCard><CriteriaCard title="Contract si disponibilitate"><label className="block text-sm text-slate-700">Interval B2B zilnic<div className="mt-1.5 flex items-center gap-2"><input type="number" value={draft.rateMin} onChange={e=>update('rateMin',Number(e.target.value))} className="h-10 w-28 rounded-xl border border-slate-200 px-3 text-sm"/><span className="text-slate-400">—</span><input type="number" value={draft.rateMax} onChange={e=>update('rateMax',Number(e.target.value))} className="h-10 w-28 rounded-xl border border-slate-200 px-3 text-sm"/><span className="text-slate-400">EUR/zi</span></div></label><CheckRow checked={draft.immediateStart} onChange={v=>update('immediateStart',v)}>Prioritizeaza disponibilitatea imediata</CheckRow></CriteriaCard><CriteriaCard title="JobsPipe" note="Apify este transportul recomandat pentru volum; Direct ramane fallback."><label className="block text-sm text-slate-700">Transport<select value={draft.jobspipeMode} onChange={e=>update('jobspipeMode',e.target.value)} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="disabled">Oprit</option><option value="apify">Apify - recomandat pentru volum</option><option value="direct">JobsPipe Direct - fallback</option></select></label>{draft.jobspipeMode==='apify'&&<label className="block text-sm text-slate-700">Maximum joburi brute / rulare<input type="number" min="100" max="20000" step="100" value={draft.jobspipeApifyMaxItems} onChange={e=>update('jobspipeApifyMaxItems',Number(e.target.value))} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 px-3 text-sm"/></label>}{draft.jobspipeMode==='direct'&&<><label className="block text-sm text-slate-700">Buget credite / rulare<input type="number" min="1" max="1000" value={draft.jobspipeDirectRunBudget} onChange={e=>update('jobspipeDirectRunBudget',Number(e.target.value))} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 px-3 text-sm"/></label><label className="block text-sm text-slate-700">Prag lunar local<input type="number" min="1" max="100000" value={draft.jobspipeDirectMonthlyGuard} onChange={e=>update('jobspipeDirectMonthlyGuard',Number(e.target.value))} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 px-3 text-sm"/></label></>}</CriteriaCard><CriteriaCard title="Excluderi" className="md:col-span-2"><div className="grid gap-4 md:grid-cols-2"><div><select defaultValue="" onChange={e=>{addExclusion(e.target.value);e.target.value='';}} className="h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-700"><option value="">Adauga excludere de rol/companie</option>{EXCLUSION_SUGGESTIONS.map(x=><option key={x}>{x}</option>)}</select><div className="mt-2 flex flex-wrap gap-2">{draft.exclusions.map(x=><button key={x} onClick={()=>removeExclusion(x)} className="inline-flex items-center gap-1 rounded-full bg-slate-100 px-2.5 py-1 text-xs font-medium text-slate-600">{x}<Icon name="close" className="h-3 w-3"/></button>)}</div></div><div className="space-y-3"><RegionSelector label="Regiuni excluse" values={draft.excludedRegions} onChange={v=>update('excludedRegions',v)}/><ChipsSelector label="Tari excluse" values={draft.excludedCountries} onChange={v=>update('excludedCountries',v)} options={COUNTRY_OPTIONS} placeholder="Adauga tara exclusa"/></div></div>{conflict&&<div className="rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">Exista un conflict intre includerile si excluderile teritoriale. Elimina suprapunerea pentru a salva.</div>}<div className="text-xs text-slate-400">Remote Worldwide ramane eligibil chiar daca este exclusa o regiune.</div></CriteriaCard></div><div className="flex items-center justify-between rounded-2xl border border-slate-200 bg-white px-5 py-4 shadow-sm"><span className={cx('text-sm font-medium',dirty?'text-amber-600':'text-slate-500')}>{dirty?'Modificari nesalvate':'Preferinte salvate'}</span><button onClick={onSave} disabled={!dirty||saving||conflict} className="h-10 rounded-xl border border-slate-300 bg-white px-4 text-sm font-semibold text-slate-800 shadow-sm hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-50">{saving?'Se salveaza...':'Salveaza preferintele'}</button></div></div>;}

function SourceModal({source,onClose,onSave,saving}){const[form,setForm]=useState(()=>source?{name:source.name,url:source.url,category:source.category,active:source.active}:{name:'',url:'',category:'Job boards si agregatoare',active:true});return<><button className="fixed inset-0 z-50 bg-slate-950/30" onClick={onClose}/><div className="fixed left-1/2 top-1/2 z-[70] w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 rounded-2xl border border-slate-200 bg-white p-5 shadow-2xl"><div className="flex items-center justify-between"><h2 className="font-display text-lg font-bold text-slate-900">{source?'Editeaza sursa':'Adauga sursa'}</h2><button onClick={onClose} className="grid h-8 w-8 place-items-center rounded-lg hover:bg-slate-100"><Icon name="close"/></button></div><div className="mt-4 space-y-3">{[['name','Nume'],['url','URL'],['category','Categorie']].map(([key,label])=><label key={key} className="block text-sm text-slate-700">{label}<input value={form[key]} onChange={e=>setForm(v=>({...v,[key]:e.target.value}))} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 px-3 text-sm"/></label>)}<CheckRow checked={form.active} onChange={active=>setForm(v=>({...v,active}))}>Activa</CheckRow>{source&&<div className="rounded-xl bg-slate-50 px-3 py-2 text-xs text-slate-500">Connector disponibil: {source.connectorAvailable?'Da':'Nu'}</div>}</div><div className="mt-5 flex justify-end gap-2"><button onClick={onClose} className="h-9 rounded-xl border border-slate-200 px-3 text-sm font-medium text-slate-600">Renunta</button><button disabled={saving||!form.name||!form.url||!form.category} onClick={()=>onSave(form)} className="h-9 rounded-xl bg-blue-600 px-4 text-sm font-semibold text-white disabled:opacity-50">{saving?'Se salveaza...':'Salveaza'}</button></div></div></>;}
function SourcesPage({sources,setSources,notify,token}){const[query,setQuery]=useState(''),[sort,setSort]=useState('name'),[editing,setEditing]=useState(null),[modalOpen,setModalOpen]=useState(false),[saving,setSaving]=useState(false);const rows=useMemo(()=>{const q=query.toLowerCase();return sources.filter(s=>`${s.name} ${s.category} ${s.url}`.toLowerCase().includes(q)).sort((a,b)=>sort==='status'?Number(b.active)-Number(a.active)||a.name.localeCompare(b.name):a.name.localeCompare(b.name));},[sources,query,sort]);const groups=useMemo(()=>rows.reduce((acc,source)=>{(acc[source.category]||=[]).push(source);return acc;},{}),[rows]);const applyCatalog=payload=>setSources((payload?.catalog?.sources||payload?.sources||[]).map(normalizeSource));const saveSource=async form=>{setSaving(true);try{const payload=await commandApi(editing?`/sources/${encodeURIComponent(editing.id)}`:'/sources',token,{method:editing?'PUT':'POST',body:JSON.stringify(form)});applyCatalog(payload);notify(editing?'Sursa a fost actualizata.':'Sursa a fost adaugata.','success');setModalOpen(false);setEditing(null);}catch(error){notify(`Sursa nu a putut fi salvata: ${error.message}`,'error');}finally{setSaving(false);}};const toggle=async source=>{try{const payload=await commandApi(`/sources/${encodeURIComponent(source.id)}`,token,{method:'PUT',body:JSON.stringify({active:!source.active})});applyCatalog(payload);notify(`Sursa este acum ${source.active?'inactiva':'activa'}.`,'success');}catch(error){notify(`Starea sursei nu a putut fi salvata: ${error.message}`,'error');}};const remove=async source=>{if(!window.confirm(`Elimini definitiv sursa "${source.name}"?`))return;try{const payload=await commandApi(`/sources/${encodeURIComponent(source.id)}`,token,{method:'DELETE'});applyCatalog(payload);notify('Sursa a fost eliminata.','success');}catch(error){notify(`Sursa nu a putut fi eliminata: ${error.message}`,'error');}};return<div className="space-y-4"><div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex flex-col gap-3 sm:flex-row"><label className="relative flex-1"><Icon name="search" className="absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Cauta o sursa" className="h-10 w-full rounded-xl border border-slate-200 bg-slate-50 pl-10 pr-3 text-sm outline-none"/></label><select value={sort} onChange={e=>setSort(e.target.value)} className="h-10 rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-600"><option value="name">Nume A-Z</option><option value="status">Surse active primele</option></select><button onClick={()=>{setEditing(null);setModalOpen(true);}} className="inline-flex h-10 items-center gap-2 rounded-xl bg-blue-600 px-4 text-sm font-semibold text-white"><Icon name="plus"/> Adauga sursa</button></div></div>{Object.entries(groups).map(([category,items])=><section key={category} className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex items-center justify-between border-b border-slate-100 px-5 py-3"><h2 className="font-display text-sm font-bold text-slate-900">{category}</h2><span className="text-xs text-slate-400">{items.length} surse</span></div><div className="divide-y divide-slate-100">{items.map(source=><div key={source.id} className="flex items-center gap-3 px-5 py-3"><a href={source.url} target="_blank" rel="noopener noreferrer" className="min-w-0 flex-1 truncate text-sm font-medium text-slate-700 hover:text-slate-950">{source.name} <span className="text-slate-400">↗</span></a><span className={cx('hidden rounded-full px-2 py-1 text-[11px] font-medium sm:inline-flex',source.connectorAvailable?'bg-blue-50 text-blue-700':'bg-slate-100 text-slate-500')}>Connector: {source.connectorAvailable?'Da':'Nu'}</span><button onClick={()=>toggle(source)} className={cx('inline-flex items-center gap-2 rounded-full px-2.5 py-1 text-xs font-medium',source.active?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-500')}><span className={cx('h-2 w-2 rounded-full',source.active?'bg-emerald-500':'bg-slate-400')}/>{source.active?'Activa':'Inactiva'}</button><button onClick={()=>{setEditing(source);setModalOpen(true);}} className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700"><Icon name="edit"/></button><button onClick={()=>remove(source)} className="grid h-8 w-8 place-items-center rounded-lg text-slate-400 hover:bg-red-50 hover:text-red-600"><Icon name="trash"/></button></div>)}</div></section>)}{!rows.length&&<div className="rounded-2xl border border-slate-200 bg-white py-12 text-center text-sm text-slate-500 shadow-sm">Nicio sursa gasita.</div>}{modalOpen&&<SourceModal source={editing} saving={saving} onClose={()=>{setModalOpen(false);setEditing(null);}} onSave={saveSource}/>}</div>;}

function LogsPage({runs}){const[open,setOpen]=useState(null);if(!runs.length)return<div className="rounded-2xl border border-slate-200 bg-white p-8 text-center text-sm text-slate-500 shadow-sm">Nu exista inca istoric de rulari.</div>;return<div className="space-y-3">{runs.slice(0,10).map(run=><section key={run.run_id} className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><button onClick={()=>setOpen(open===run.run_id?null:run.run_id)} className="grid w-full gap-3 px-5 py-4 text-left sm:grid-cols-[160px_120px_110px_1fr_100px] sm:items-center"><div><div className="text-sm font-semibold text-slate-900">{formatRunTime(run.completed_at||run.started_at)}</div><div className="text-xs text-slate-400">{run.run_id}</div></div><span className={cx('inline-flex w-fit rounded-full px-2 py-1 text-xs font-semibold',run.status==='completed'?'bg-emerald-50 text-emerald-700':run.status==='completed_with_errors'?'bg-amber-50 text-amber-700':'bg-red-50 text-red-700')}>{run.status}</span><div className="text-xs text-slate-600">{run.sources_processed??0} surse</div><div className="text-xs text-slate-500">{run.records_inspected??0} brute · {run.jobs_published??0} publicate · {run.excluded??0} excluse</div><div className="text-right text-xs text-slate-400">{run.duration_seconds!=null?`${run.duration_seconds}s`:'—'} <Icon name="chevronDown" className={cx('ml-1 inline h-3 w-3 transition',open===run.run_id&&'rotate-180')}/></div></button>{open===run.run_id&&<div className="border-t border-slate-100 bg-slate-50/60 px-5 py-4"><div className="grid gap-3 text-xs text-slate-600 md:grid-cols-3"><div><span className="text-slate-400">Trigger:</span> {run.trigger||'—'}</div><div><span className="text-slate-400">Transport:</span> {run.transport||'—'}</div><div><span className="text-slate-400">Publicare:</span> {run.publication||'—'}</div></div>{run.source_results?.length>0&&<div className="mt-4 space-y-2">{run.source_results.map((item,i)=><div key={i} className="rounded-xl border border-slate-200 bg-white px-3 py-2 text-xs"><div className="flex flex-wrap gap-x-4 gap-y-1"><strong>{item.source||item.connector}</strong><span>{item.query}</span><span>{item.status}</span><span>{item.records??0} rezultate</span></div>{item.error&&<div className="mt-1 text-red-600">{item.error}</div>}</div>)}</div>}{run.limitations?.length>0&&<div className="mt-3 text-xs text-amber-700">{run.limitations.join(' · ')}</div>}</div>}</section>)}</div>;}

function App(){
  const[clientId,setClientId]=useState(null),[auth,setAuth]=useState({status:'signed-out',token:null,email:null,error:null}),[dataState,setDataState]=useState({status:'idle',error:null});
  const[jobs,setJobs]=useState([]),[applications,setApplications]=useState([]),[sources,setSources]=useState([]),[runStatus,setRunStatus]=useState(null),[runHistory,setRunHistory]=useState([]),[canonicalConfig,setCanonicalConfig]=useState(null);
  const[savedCriteria,setSavedCriteria]=useState(criteriaFromConfig({})),[draftCriteria,setDraftCriteria]=useState(criteriaFromConfig({})),[view,setView]=useState('jobs');
  const[filters,setFilters]=useState({search:'',quick:'all',freshness:24,workModes:[...ALL_WORK_MODES],sort:'fit-desc'}),[kpiFilter,setKpiFilter]=useState('all'),[detailJob,setDetailJob]=useState(null),[running,setRunning]=useState(false),[saving,setSaving]=useState(false),[toast,setToast]=useState(null);
  const[archivedKeys,setArchivedKeys]=useState(()=>{try{return JSON.parse(localStorage.getItem('archivedJobKeys')||'[]')}catch{return[]}});
  const notify=useCallback((message,type='info')=>{const id=Date.now();setToast({id,message,type});window.setTimeout(()=>setToast(current=>current?.id===id?null:current),3500);},[]);
  useEffect(()=>{commandApi('/auth/config',null).then(config=>{if(!config?.configured||!config?.client_id)throw new Error('Autentificarea Google nu este configurata complet.');setClientId(config.client_id);}).catch(error=>setAuth(current=>({...current,error:error.message})));},[]);
  const clearData=useCallback(()=>{setJobs([]);setApplications([]);setSources([]);setRunStatus(null);setRunHistory([]);setCanonicalConfig(null);},[]);
  const loadData=useCallback(async token=>{setDataState({status:'loading',error:null});clearData();try{const[jobPayload,statusPayload,historyPayload,applicationPayload,sourcePayload,configPayload]=await Promise.all([fetchJson('/data/jobs.json',token),fetchJson('/data/run-status.json',token),fetchJson('/data/run-history.json',token),fetchJson('/data/applications.json',token),fetchJson('/data/sources.json',token),fetchJson('/data/search-config.json',token)]);validateContract(jobPayload,'jobs.json');validateContract(statusPayload,'run-status.json');validateContract(historyPayload,'run-history.json');validateContract(configPayload,'search-config.json');const criteria=criteriaFromConfig(configPayload);setJobs((jobPayload.jobs||[]).map(normalizeJob));setApplications((applicationPayload.applications||[]).map(normalizeApplication));setSources((sourcePayload.sources||[]).map(normalizeSource));setRunStatus(statusPayload);setRunHistory(historyPayload.runs||[]);setCanonicalConfig(configPayload);setSavedCriteria(criteria);setDraftCriteria(criteria);setFilters(current=>({...current,freshness:criteria.freshness||24}));setDataState({status:'ready',error:null});}catch(error){setDataState({status:'error',error});throw error;}},[clearData]);
  const handleCredential=useCallback(async credential=>{setAuth({status:'authenticating',token:null,email:null,error:null});try{const session=await commandApi('/auth/session',credential,{method:'POST'});setAuth({status:'authenticated',token:credential,email:session?.email||null,error:null});try{await loadData(credential);notify('Autentificare Google reusita.','success');}catch(error){notify(`Autentificarea a reusit, dar datele nu s-au incarcat: ${error.message}`,'error');}}catch(error){const message=error.status===403?'Contul Google nu este autorizat pentru aceasta aplicatie.':`Autentificare esuata: ${error.message}`;setAuth({status:'signed-out',token:null,email:null,error:message});}},[loadData,notify]);
  const logout=useCallback(()=>{try{window.google?.accounts?.id?.disableAutoSelect();}catch{}setAuth({status:'signed-out',token:null,email:null,error:null});setDataState({status:'idle',error:null});clearData();setDetailJob(null);notify('Contul Google a fost deconectat din aceasta sesiune.','info');},[clearData,notify]);
  const retryData=useCallback(()=>{if(auth.token)loadData(auth.token).then(()=>notify('Datele au fost reincarcate.','success')).catch(error=>notify(`Incarcarea a esuat: ${error.message}`,'error'));},[auth.token,loadData,notify]);
  const activeJobs=useMemo(()=>jobs.filter(job=>!archivedKeys.includes(jobKey(job))),[jobs,archivedKeys]);
  const baseRows=useMemo(()=>view==='applications'?applications:view==='review'?activeJobs.filter(job=>job.status==='review'):activeJobs,[view,applications,activeJobs]);
  const threshold=savedCriteria.fitThreshold||80;
  const modeFreshRows=useMemo(()=>view==='applications'?baseRows:baseRows.filter(job=>ageHours(job.date_posted,job.age)<=filters.freshness&&filters.workModes.includes(job.mode)),[view,baseRows,filters.freshness,filters.workModes]);
  const filteredRows=useMemo(()=>{if(view==='applications')return[...baseRows];const q=filters.search.trim().toLowerCase();let rows=modeFreshRows.filter(job=>{const quick=filters.quick==='all'||(filters.quick==='high'&&job.fit!==null&&job.fit>=threshold)||(filters.quick==='b2b'&&job.b2b);const kpi=kpiFilter==='all'||(kpiFilter==='new'&&ageHours(job.date_posted,job.age)<=24)||(kpiFilter==='high'&&job.fit!==null&&job.fit>=threshold)||(kpiFilter==='repost'&&job.repost)||(kpiFilter==='remote'&&job.mode==='Remote');const text=`${job.title} ${job.company} ${job.description} ${job.source} ${job.location} ${(job.countries||[]).join(' ')}`.toLowerCase();return quick&&kpi&&(!q||text.includes(q));});return[...rows].sort(filters.sort==='fit-asc'?(a,b)=>(a.fit??Number.MAX_SAFE_INTEGER)-(b.fit??Number.MAX_SAFE_INTEGER)||a.age-b.age:(a,b)=>(b.fit??-1)-(a.fit??-1)||a.age-b.age);},[view,baseRows,modeFreshRows,filters.quick,filters.search,filters.sort,threshold,kpiFilter]);
  const quickCounts=useMemo(()=>({all:modeFreshRows.length,high:modeFreshRows.filter(j=>j.fit!==null&&j.fit>=threshold).length,b2b:modeFreshRows.filter(j=>j.b2b).length}),[modeFreshRows,threshold]);
  const dashboardJobs=useMemo(()=>activeJobs.filter(job=>filters.workModes.includes(job.mode)),[activeJobs,filters.workModes]);
  const metrics=useMemo(()=>({jobs:dashboardJobs.filter(j=>ageHours(j.date_posted,j.age)<=24).length,high:dashboardJobs.filter(j=>j.fit>=threshold).length,reposts:dashboardJobs.filter(j=>j.repost).length,remote:dashboardJobs.filter(j=>j.mode==='Remote').length,threshold}),[dashboardJobs,threshold]);
  const counts=useMemo(()=>({jobs:activeJobs.length,review:activeJobs.filter(j=>j.status==='review').length,applications:applications.length}),[activeJobs,applications]);
  const archiveJob=job=>{const next=[...new Set([...archivedKeys,jobKey(job)])];setArchivedKeys(next);localStorage.setItem('archivedJobKeys',JSON.stringify(next));notify('Job arhivat local.','info');};
  const pollRun=useCallback(async(previousRunId,previousCompletedAt)=>{for(let attempt=0;attempt<60;attempt+=1){await new Promise(resolve=>setTimeout(resolve,5000));try{const status=await fetchJson(`/data/run-status.json?t=${Date.now()}`,auth.token);if(status.run_id===previousRunId&&status.completed_at===previousCompletedAt)continue;await loadData(auth.token);notify(status.status==='failed'?'Verificarea s-a terminat cu eroare.':`Verificare finalizata: ${status.jobs_published??0} joburi publicate din ${status.sources_processed??0} surse.`,status.status==='failed'?'error':'success');return;}catch{}}notify('Verificarea a fost pornita, dar rezultatul nu a fost publicat inca.','info');},[auth.token,loadData,notify]);
  const runSearch=useCallback(async()=>{if(!auth.token||running)return;setRunning(true);const previousRunId=runStatus?.run_id||null,previousCompletedAt=runStatus?.completed_at||null;try{await commandApi('/commands/run',auth.token,{method:'POST'});notify('Verificarea a fost pornita in GitHub Actions.','info');await pollRun(previousRunId,previousCompletedAt);}catch(error){if(error.status===409){notify('Exista deja o verificare in curs.','info');await pollRun(previousRunId,previousCompletedAt);}else notify(`Nu am putut porni verificarea: ${error.message}`,'error');}finally{setRunning(false);}},[auth.token,running,runStatus,notify,pollRun]);
  const saveCriteria=useCallback(async()=>{if(!auth.token||saving)return;if(geographyConflicts(draftCriteria)){notify('Rezolva conflictul dintre includerile si excluderile teritoriale.','error');return;}setSaving(true);try{await commandApi('/config',auth.token,{method:'PUT',body:JSON.stringify(draftCriteria)});setSavedCriteria(draftCriteria);setCanonicalConfig(current=>current?{...current,freshness_hours:draftCriteria.freshness,fit_threshold:draftCriteria.fitThreshold,target_regions:draftCriteria.targetRegions,target_country_codes:draftCriteria.targetCountries,excluded_regions:draftCriteria.excludedRegions,excluded_country_codes:draftCriteria.excludedCountries,jobspipe_mode:draftCriteria.jobspipeMode,jobspipe_apify_max_items_per_run:draftCriteria.jobspipeApifyMaxItems,jobspipe_credit_budget_per_run:draftCriteria.jobspipeDirectRunBudget,jobspipe_monthly_credit_guard:draftCriteria.jobspipeDirectMonthlyGuard}:current);setFilters(current=>({...current,freshness:draftCriteria.freshness}));notify('Preferintele au fost salvate. O noua verificare va porni automat.','success');}catch(error){notify(`Preferintele nu au putut fi salvate: ${error.message}`,'error');}finally{setSaving(false);}},[auth.token,saving,draftCriteria,notify]);
  if(auth.status!=='authenticated')return<><SignedOutScreen clientId={clientId} authError={auth.error} authStatus={auth.status} onCredential={handleCredential}/><Toast toast={toast}/></>;
  return<div className="min-h-screen bg-slate-50 md:flex"><Sidebar view={view} onView={v=>{setView(v);if(v!=='jobs')setKpiFilter('all');}} counts={counts} runStatus={runStatus}/><main className="min-w-0 flex-1"><div className="mx-auto w-full max-w-[1400px] space-y-5 px-4 py-5 sm:px-6 lg:px-8 lg:py-7"><Header view={view} email={auth.email} running={running} onRun={runSearch} onLogout={logout}/>{dataState.status==='loading'&&<LoadingPanel/>}{dataState.status==='error'&&<ErrorPanel error={dataState.error} onRetry={retryData}/>} {dataState.status==='ready'&&<>{view==='jobs'&&<KPIGrid metrics={metrics} freshness={filters.freshness} selected={kpiFilter} onSelect={setKpiFilter}/>} {(view==='jobs'||view==='review')&&<Filters filters={filters} setFilters={setFilters} counts={quickCounts} defaultFreshness={savedCriteria.freshness} onResetKpi={()=>setKpiFilter('all')}/>} {(view==='jobs'||view==='review'||view==='applications')&&<JobTable rows={filteredRows} threshold={threshold} onDetails={setDetailJob} onArchive={archiveJob}/>} {view==='criteria'&&<CriteriaPage draft={draftCriteria} setDraft={setDraftCriteria} saved={savedCriteria} onSave={saveCriteria} saving={saving}/>} {view==='sources'&&<SourcesPage sources={sources} setSources={setSources} notify={notify} token={auth.token}/>} {view==='logs'&&<LogsPage runs={runHistory}/>}</>}</div></main><DetailDrawer job={detailJob} threshold={threshold} onClose={()=>setDetailJob(null)}/><Toast toast={toast}/></div>;
}

createRoot(document.getElementById('root')).render(<React.StrictMode><App/></React.StrictMode>);
